PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?sex (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?sex_record a sphn:AdministrativeSex ;
                sphn:hasCode ?sex_code .
    ?sex_code a ?sex_concept .
  }
  VALUES (?sex_concept ?sex) {
    (snomed:248153007         "male")
    (snomed:248152002         "female")
    (snomed:32570681000036106 "indeterminate")
  }
}
GROUP BY ?sex
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?care_type (COUNT(DISTINCT ?case) AS ?stays) (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasCareHandling ?care_handling .
    ?care_handling sphn:hasTypeCode ?type_code .
    ?type_code a ?type_concept .
  }
  VALUES (?type_concept ?care_type) {
    (snomed:394656005 "inpatient")
    (snomed:371883000 "outpatient")
    (snomed:304903009 "day care")
  }
}
GROUP BY ?care_type
ORDER BY DESC(?stays)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT (COUNT(DISTINCT ?case) AS ?stays)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_days)
       (MIN(?days) AS ?min_days)
       (MAX(?days) AS ?max_days)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasAdmissionDateTime ?admission ;
          sphn:hasDischargeDateTime ?discharge .
  }
  BIND (bif:datediff("day", ?admission, ?discharge) AS ?days)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?year (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?lab_event a sphn:LabTestEvent ;
               sphn:hasDateTime ?performed .
  }
  BIND (YEAR(?performed) AS ?year)
  FILTER (?year >= 2000 && ?year <= 2009)
}
GROUP BY ?year
ORDER BY ?year

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?year (COUNT(DISTINCT ?death) AS ?deaths) (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?death a sphn:Death ;
           sphn:hasReportDateTime ?reported .
  }
  BIND (YEAR(?reported) AS ?year)
  FILTER (?year >= 2015 && ?year <= 2025)
}
GROUP BY ?year
ORDER BY ?year

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?civil_status (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?status a sphn:CivilStatus ;
            sphn:hasCode ?status_code .
    ?status_code a ?status_concept .
  }
  VALUES (?status_concept ?civil_status) {
    (snomed:87915002  "married")
    (snomed:125681006 "single")
    (snomed:20295000  "divorced")
    (snomed:33553000  "widowed")
    (snomed:266945001 "separated from partner")
    (snomed:14012001  "unmarried partnership")
  }
}
GROUP BY ?civil_status
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?bmi) AS ?bmi_records)
       (ROUND(10 * AVG(?value)) / 10 AS ?avg_bmi)
WHERE {
  GRAPH ?g {
    ?bmi a sphn:BodyMassIndex ;
         sphn:hasQuantity ?quantity .
    ?quantity sphn:hasValue ?value .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?graft_type (COUNT(DISTINCT ?g) AS ?patients) (COUNT(DISTINCT ?transplant) AS ?transplants)
WHERE {
  GRAPH ?g {
    ?transplant a sphn:Transplant ;
                sphn:hasGraftTypeCode ?graft_code .
    ?graft_code a ?graft_concept .
  }
  VALUES (?graft_concept ?graft_type) {
    (snomed:15879007 "own tissue")
    (snomed:7970006  "donor")
  }
}
GROUP BY ?graft_type
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?risk (COUNT(DISTINCT ?allergy) AS ?allergies) (COUNT(DISTINCT ?g) AS ?patients)
