  VALUES (?severity_concept ?risk) {
    (snomed:723505004 "low")
    (snomed:723509005 "high")
    (snomed:723507007 "undetermined")
  }
}
GROUP BY ?risk
ORDER BY DESC(?allergies)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
