PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?reading) AS ?readings)
       (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(10 * AVG(?systolic)) / 10 AS ?avg_systolic)
       (ROUND(10 * AVG(?diastolic)) / 10 AS ?avg_diastolic)
WHERE {
  GRAPH ?g {
    ?reading a sphn:BloodPressure ;
             sphn:hasSystolicPressure ?systolic_quantity ;
             sphn:hasDiastolicPressure ?diastolic_quantity .
    ?systolic_quantity sphn:hasValue ?systolic .
    ?diastolic_quantity sphn:hasValue ?diastolic .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?cholera_patient) AS ?cholera_patients)
       (ROUND(1000.0 * COUNT(DISTINCT ?cholera_patient) / COUNT(DISTINCT ?g)) / 10 AS ?cholera_pct)
WHERE {
  GRAPH ?g {
    ?sex_record a sphn:AdministrativeSex .
  }
  OPTIONAL {
    GRAPH ?g {
      ?dx a sphn:BilledDiagnosis ;
          sphn:hasCode ?dx_code .
      ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    BIND (?g AS ?cholera_patient)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT (COUNT(DISTINCT ?g) AS ?patients_with_directive)
       (COUNT(DISTINCT ?dnr_patient) AS ?patients_do_not_resuscitate)
       (ROUND(1000.0 * COUNT(DISTINCT ?dnr_patient) / COUNT(DISTINCT ?g)) / 10 AS ?dnr_pct)
WHERE {
  GRAPH ?g {
    ?directive a sphn:ResuscitationDirective .
  }
  OPTIONAL {
    GRAPH ?g {
      ?dnr_directive a sphn:ResuscitationDirective ;
                     sphn:hasCode ?dnr_code .
      ?dnr_code a snomed:304253006 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    BIND (?g AS ?dnr_patient)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?dx) AS ?principal_cholera_diagnoses)
WHERE {
  GRAPH ?g {
    ?dx a sphn:BilledDiagnosis ;
        sphn:hasRank sphn-individual:Principal ;
        sphn:hasRecordDateTime ?recorded ;
        sphn:hasCode ?dx_code .
    ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
  FILTER (YEAR(?recorded) >= 2010 && YEAR(?recorded) <= 2020)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?radiotherapy_patients)
       (COUNT(DISTINCT ?surgery_patient) AS ?also_had_cancer_surgery)
       (ROUND(1000.0 * COUNT(DISTINCT ?surgery_patient) / COUNT(DISTINCT ?g)) / 10 AS ?pct)
WHERE {
  GRAPH ?g {
    ?radiotherapy a sphn:RadiotherapyProcedure .
  }
  OPTIONAL {
    GRAPH ?g { ?surgery a sphn:OncologySurgery . }
    BIND (?g AS ?surgery_patient)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?specialty
       (COUNT(DISTINCT ?g) AS ?cholera_patients)
       (COUNT(DISTINCT ?encounter) AS ?encounters)
WHERE {
  GRAPH ?g {
    ?dx a sphn:BilledDiagnosis ;
        sphn:hasCode ?dx_code .
    ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    ?encounter a sphn:HealthcareEncounter ;
               sphn:hasTherapeuticArea ?area .
    ?area sphn:hasSpecialtyName ?specialty_value .
  }
  BIND (STRAFTER(STR(?specialty_value), "#") AS ?specialty)
}
GROUP BY ?specialty
ORDER BY DESC(?cholera_patients) DESC(?encounters)
LIMIT 10

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients_given_drugs)
       (COUNT(DISTINCT ?ae_patient) AS ?with_adverse_event)
       (ROUND(1000.0 * COUNT(DISTINCT ?ae_patient) / COUNT(DISTINCT ?g)) / 10 AS ?adverse_event_pct)
WHERE {
  GRAPH ?g {
    ?administration a sphn:DrugAdministrationEvent .
  }
  OPTIONAL {
    GRAPH ?g { ?event a sphn:AdverseEvent . }
    BIND (?g AS ?ae_patient)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?dx) AS ?billed_diagnoses)
WHERE {
  GRAPH ?g {
    ?dx_code a icd-10-gm:10 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    ?dx sphn:hasCode ?dx_code .
    ?dx a sphn:BilledDiagnosis .
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?surgery a sphn:OncologySurgery ;
             sphn:hasStartDateTime ?surgery_start .
    ?radiotherapy a sphn:RadiotherapyProcedure ;
                  sphn:hasStartDateTime ?radiotherapy_start .
  }
  FILTER (?radiotherapy_start > ?surgery_start)
  FILTER (bif:datediff("day", ?surgery_start, ?radiotherapy_start) <= 90)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT (COUNT(DISTINCT ?g) AS ?hypertension_patients)
       (COUNT(DISTINCT ?bp_patient) AS ?with_blood_pressure_readings)
WHERE {
  GRAPH ?g {
    ?dx a sphn:BilledDiagnosis ;
        sphn:hasCode ?dx_code .
    ?dx_code a icd-10-gm:I10 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
  OPTIONAL {
    GRAPH ?g { ?reading a sphn:BloodPressure . }
    BIND (?g AS ?bp_patient)
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?care_type
       (COUNT(DISTINCT ?case) AS ?stays)
       (COUNT(DISTINCT ?case_with_procedure) AS ?stays_with_billed_procedure)
       (ROUND(1000.0 * COUNT(DISTINCT ?case_with_procedure) / COUNT(DISTINCT ?case)) / 10 AS ?pct)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasCareHandling ?care_handling .
    ?care_handling sphn:hasTypeCode ?type_code .
    ?type_code a ?type_concept .
  }
  VALUES (?type_concept ?care_type) {
    (snomed:394656005 "inpatient")
    (snomed:371883000 "outpatient")
    (snomed:304903009 "day care")
  }
  OPTIONAL {
    GRAPH ?g {
      ?procedure a sphn:BilledProcedure ;
                 sphn:hasAdministrativeCase ?case .
    }
    BIND (?case AS ?case_with_procedure)
  }
}
GROUP BY ?care_type
ORDER BY DESC(?pct)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?consent_type
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?accepted_patient) AS ?accepted)
       (COUNT(DISTINCT ?refused_patient) AS ?refused)
       (COUNT(DISTINCT ?informed_patient) AS ?informed_only)
       (ROUND(1000.0 * COUNT(DISTINCT ?refused_patient) / COUNT(DISTINCT ?g)) / 10 AS ?refused_pct)
WHERE {
  GRAPH ?g {
    ?consent a sphn:Consent ;
             sphn:hasTypeCode ?type_code .
    ?type_code a ?type_concept .
  }
  VALUES (?type_concept ?consent_type) {
    (snomed:60132005  "general")
    (snomed:69658003  "specific")
    (snomed:410529002 "no consent required")
  }
  OPTIONAL {
    GRAPH ?g {
      ?consent sphn:hasStatusCode ?accepted_code .
      ?accepted_code a snomed:385645004 .
    }
    BIND (?g AS ?accepted_patient)
  }
  OPTIONAL {
    GRAPH ?g {
      ?consent sphn:hasStatusCode ?refused_code .
      ?refused_code a snomed:443390004 .
    }
    BIND (?g AS ?refused_patient)
  }
  OPTIONAL {
    GRAPH ?g {
      ?consent sphn:hasStatusCode ?informed_code .
      ?informed_code a snomed:225795001 .
    }
    BIND (?g AS ?informed_patient)
  }
}
GROUP BY ?consent_type
ORDER BY ?consent_type

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>
PREFIX bif: <bif:>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?dx a sphn:BilledDiagnosis ;
        sphn:hasRecordDateTime ?diagnosed ;
        sphn:hasCode ?dx_code .
    ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    ?death a sphn:Death ;
           sphn:hasReportDateTime ?death_reported .
  }
  FILTER (?death_reported >= ?diagnosed)
  FILTER (bif:datediff("day", ?diagnosed, ?death_reported) <= 365)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>
PREFIX bif: <bif:>

SELECT ?cohort
       (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_days)
       (MIN(?days) AS ?min_days)
       (MAX(?days) AS ?max_days)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasAdmissionDateTime ?admission ;
          sphn:hasDischargeDateTime ?discharge .
  }
  BIND (bif:datediff("day", ?admission, ?discharge) AS ?days)
  BIND (IF(EXISTS {
             GRAPH ?g {
               ?dx a sphn:BilledDiagnosis ;
                   sphn:hasCode ?dx_code .
               ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
             }
           }, "cholera billed", "no cholera billed") AS ?cohort)
}
GROUP BY ?cohort
ORDER BY ?cohort

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX bif: <bif:>

SELECT ?radiotherapy_concept
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?radiotherapy) AS ?procedures)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_days)
       (ROUND(1000.0 * COUNT(DISTINCT ?palliative_radiotherapy) / COUNT(DISTINCT ?radiotherapy)) / 10 AS ?palliative_pct)
WHERE {
  GRAPH ?g {
    ?radiotherapy a sphn:RadiotherapyProcedure ;
                  sphn:hasCode ?radiotherapy_code ;
                  sphn:hasStartDateTime ?start ;
                  sphn:hasEndDateTime ?end .
    ?radiotherapy_code a ?radiotherapy_concept .
  }
  FILTER (STRSTARTS(STR(?radiotherapy_concept), "http://snomed.info/id/"))
  BIND (bif:datediff("day", ?start, ?end) AS ?days)
  OPTIONAL {
    GRAPH ?g {
      ?radiotherapy sphn:hasIntent ?intent .
      ?intent sphn:hasCode ?intent_code .
      ?intent_code a snomed:363676003 .
    }
    BIND (?radiotherapy AS ?palliative_radiotherapy)
  }
}
GROUP BY ?radiotherapy_concept
ORDER BY DESC(?procedures)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?encounter_group
       (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(1000.0 * COUNT(DISTINCT ?g) / ?all_patients) / 10 AS ?pct)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?any_g) AS ?all_patients)
    WHERE {
      GRAPH ?any_g { ?any_encounter a sphn:HealthcareEncounter . }
    }
  }
  {
    SELECT ?g (COUNT(DISTINCT ?encounter) AS ?encounters)
    WHERE {
      GRAPH ?g { ?encounter a sphn:HealthcareEncounter . }
    }
    GROUP BY ?g
  }
  BIND (IF(?encounters = 1, "1",
        IF(?encounters <= 5, "2-5",
        IF(?encounters <= 20, "6-20", "more than 20"))) AS ?encounter_group)
}
GROUP BY ?encounter_group ?all_patients
ORDER BY ?encounter_group

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>
PREFIX bif: <bif:>

SELECT ?coverage
       (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_stay_days)
       (SUM(?has_cholera) AS ?cholera_patients)
       (ROUND(1000.0 * SUM(?has_cholera) / COUNT(DISTINCT ?g)) / 10 AS ?cholera_pct)
WHERE {
  {
    SELECT DISTINCT ?g ?coverage ?days ?has_cholera
    WHERE {
      GRAPH ?g {
        ?insurance a sphn:InsuranceStatus ;
                   sphn:hasCoverageType ?coverage_type .
        ?case a sphn:AdministrativeCase ;
              sphn:hasAdmissionDateTime ?admission ;
              sphn:hasDischargeDateTime ?discharge .
      }
      BIND (STRAFTER(STR(?coverage_type), "#") AS ?coverage)
      BIND (bif:datediff("day", ?admission, ?discharge) AS ?days)
      BIND (IF(EXISTS {
                 GRAPH ?g {
                   ?dx a sphn:BilledDiagnosis ;
                       sphn:hasCode ?dx_code .
                   ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
                 }
               }, 1, 0) AS ?has_cholera)
    }
  }
}
GROUP BY ?coverage
ORDER BY DESC(?cholera_pct)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?sex
       (COUNT(DISTINCT ?bmi_patient) AS ?patients_with_bmi)
       (ROUND(10 * AVG(?bmi_value)) / 10 AS ?avg_bmi)
       (COUNT(DISTINCT ?bp_patient) AS ?patients_with_blood_pressure)
       (ROUND(10 * AVG(?systolic)) / 10 AS ?avg_systolic)
WHERE {
  GRAPH ?g {
    ?sex_record a sphn:AdministrativeSex ;
                sphn:hasCode ?sex_code .
    ?sex_code a ?sex_concept .
  }
  VALUES (?sex_concept ?sex) {
    (snomed:248153007         "male")
    (snomed:248152002         "female")
    (snomed:32570681000036106 "indeterminate")
  }
  {
    GRAPH ?g {
      ?bmi a sphn:BodyMassIndex ;
           sphn:hasQuantity ?bmi_quantity .
      ?bmi_quantity sphn:hasValue ?bmi_value .
    }
    BIND (?g AS ?bmi_patient)
  }
  UNION
  {
    GRAPH ?g {
      ?reading a sphn:BloodPressure ;
               sphn:hasSystolicPressure ?systolic_quantity .
      ?systolic_quantity sphn:hasValue ?systolic .
    }
    BIND (?g AS ?bp_patient)
  }
}
GROUP BY ?sex
ORDER BY ?sex

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT (MIN(?days) AS ?median_days) ?avg_days ?stays
WHERE {
  {
    SELECT (COUNT(DISTINCT ?all_case) AS ?stays)
           (ROUND(10 * AVG(bif:datediff("day", ?all_admission, ?all_discharge))) / 10 AS ?avg_days)
    WHERE {
      GRAPH ?all_g {
        ?all_case a sphn:AdministrativeCase ;
                  sphn:hasAdmissionDateTime ?all_admission ;
                  sphn:hasDischargeDateTime ?all_discharge .
      }
    }
  }
  {
    SELECT ?days (COUNT(DISTINCT ?case) AS ?stays_up_to_days)
    WHERE {
      {
        SELECT DISTINCT ?days
        WHERE {
          GRAPH ?length_g {
            ?length_case a sphn:AdministrativeCase ;
                         sphn:hasAdmissionDateTime ?length_admission ;
                         sphn:hasDischargeDateTime ?length_discharge .
          }
          BIND (bif:datediff("day", ?length_admission, ?length_discharge) AS ?days)
        }
      }
      GRAPH ?g {
        ?case a sphn:AdministrativeCase ;
              sphn:hasAdmissionDateTime ?admission ;
              sphn:hasDischargeDateTime ?discharge .
      }
      FILTER (bif:datediff("day", ?admission, ?discharge) <= ?days)
    }
    GROUP BY ?days
  }
  FILTER (2 * ?stays_up_to_days >= ?stays)
}
GROUP BY ?avg_days ?stays

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>

SELECT ?reaction_type
       (COUNT(DISTINCT ?allergy) AS ?records)
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?confirmed_allergy) AS ?confirmed)
       (COUNT(DISTINCT ?suspected_allergy) AS ?suspected)
       (COUNT(DISTINCT ?refuted_allergy) AS ?refuted)
       (COUNT(DISTINCT ?error_allergy) AS ?entered_in_error)
       (ROUND(1000.0 * COUNT(DISTINCT ?confirmed_allergy) / COUNT(DISTINCT ?allergy)) / 10 AS ?confirmed_pct)
WHERE {
  GRAPH ?g {
    ?allergy a sphn:Allergy ;
             sphn:hasReactionTypeCode ?reaction_code .
    ?reaction_code a ?reaction_concept .
  }
  VALUES (?reaction_concept ?reaction_type) {
    (snomed:609328004 "allergy")
    (snomed:782197009 "intolerance")
  }
  OPTIONAL {
    GRAPH ?g {
      ?allergy sphn:hasVerificationStatusCode ?confirmed_code .
      ?confirmed_code a snomed:410605003 .
    }
    BIND (?allergy AS ?confirmed_allergy)
  }
  OPTIONAL {
    GRAPH ?g {
      ?allergy sphn:hasVerificationStatusCode ?suspected_code .
      ?suspected_code a snomed:415684004 .
    }
    BIND (?allergy AS ?suspected_allergy)
  }
  OPTIONAL {
    GRAPH ?g {
      ?allergy sphn:hasVerificationStatusCode ?refuted_code .
      ?refuted_code a snomed:723511001 .
    }
    BIND (?allergy AS ?refuted_allergy)
  }
  OPTIONAL {
    GRAPH ?g {
      ?allergy sphn:hasVerificationStatusCode ?error_code .
      ?error_code a snomed:723510000 .
    }
    BIND (?allergy AS ?error_allergy)
  }
}
GROUP BY ?reaction_type
ORDER BY ?reaction_type

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT ?specialty
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?encounter) AS ?encounters)
       (ROUND(10 * AVG(?hours)) / 10 AS ?avg_hours)
       (MAX(?hours) AS ?max_hours)
WHERE {
  GRAPH ?g {
    ?encounter a sphn:HealthcareEncounter ;
               sphn:hasTherapeuticArea ?area ;
               sphn:hasStartDateTime ?start ;
               sphn:hasEndDateTime ?end .
    ?area sphn:hasSpecialtyName ?specialty_value .
  }
  BIND (STRAFTER(STR(?specialty_value), "#") AS ?specialty)
  BIND (bif:datediff("hour", ?start, ?end) AS ?hours)
}
GROUP BY ?specialty
ORDER BY DESC(?encounters)
LIMIT 5

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?year
       (COUNT(DISTINCT ?g) AS ?patients_with_billed_diagnosis)
       (COUNT(DISTINCT ?cholera_patient) AS ?cholera_patients)
       (ROUND(1000.0 * COUNT(DISTINCT ?cholera_patient) / COUNT(DISTINCT ?g)) / 10 AS ?cholera_pct)
WHERE {
  GRAPH ?g {
    ?dx a sphn:BilledDiagnosis ;
        sphn:hasRecordDateTime ?recorded .
  }
  BIND (YEAR(?recorded) AS ?year)
  FILTER (?year >= 2010 && ?year <= 2025)
  OPTIONAL {
    GRAPH ?g {
      ?dx sphn:hasCode ?dx_code .
      ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    BIND (?g AS ?cholera_patient)
  }
}
GROUP BY ?year
ORDER BY ?year

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX bif: <bif:>

SELECT ?directive_group
       (COUNT(DISTINCT ?g) AS ?patients)
       (SUM(?died) AS ?patients_with_death)
       (ROUND(1000.0 * SUM(?died) / COUNT(DISTINCT ?g)) / 10 AS ?death_pct)
       (ROUND(10 * AVG(?days)) / 10 AS ?avg_stay_days)
WHERE {
  {
    SELECT DISTINCT ?g ?directive_group
    WHERE {
      {
        GRAPH ?g {
          ?dnr a sphn:ResuscitationDirective ;
               sphn:hasCode ?dnr_code .
          ?dnr_code a snomed:304253006 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        }
        BIND ("do not resuscitate" AS ?directive_group)
      }
      UNION
      {
        GRAPH ?g {
          ?resus a sphn:ResuscitationDirective ;
                 sphn:hasCode ?resus_code .
          ?resus_code a snomed:304252001 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        }
        BIND ("resuscitate" AS ?directive_group)
      }
    }
  }
  GRAPH ?g {
    ?case a sphn:AdministrativeCase ;
          sphn:hasAdmissionDateTime ?admission ;
          sphn:hasDischargeDateTime ?discharge .
  }
  BIND (bif:datediff("day", ?admission, ?discharge) AS ?days)
  BIND (IF(EXISTS { GRAPH ?g { ?death a sphn:Death . } }, 1, 0) AS ?died)
}
GROUP BY ?directive_group
ORDER BY ?directive_group

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
       (ROUND(100 * AVG(?diagnoses)) / 100 AS ?avg_diagnoses_per_patient)
       (MAX(?diagnoses) AS ?max_diagnoses_per_patient)
       (SUM(IF(?diagnoses > 1, 1, 0)) AS ?patients_with_more_than_one)
WHERE {
  {
    SELECT ?g (COUNT(DISTINCT ?dx) AS ?diagnoses)
    WHERE {
      GRAPH ?g { ?dx a sphn:BilledDiagnosis . }
    }
    GROUP BY ?g
  }
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT ?year
       (SUM(?is_cancer_surgery) AS ?cancer_surgeries)
       (SUM(?is_radiotherapy) AS ?radiotherapy_procedures)
       (SUM(?is_billed_procedure) AS ?billed_procedures)
WHERE {
  {
    GRAPH ?g { ?procedure a sphn:OncologySurgery ; sphn:hasStartDateTime ?start . }
    BIND (1 AS ?is_cancer_surgery) BIND (0 AS ?is_radiotherapy) BIND (0 AS ?is_billed_procedure)
  }
  UNION
  {
    GRAPH ?g { ?procedure a sphn:RadiotherapyProcedure ; sphn:hasStartDateTime ?start . }
    BIND (0 AS ?is_cancer_surgery) BIND (1 AS ?is_radiotherapy) BIND (0 AS ?is_billed_procedure)
  }
  UNION
  {
    GRAPH ?g { ?procedure a sphn:BilledProcedure ; sphn:hasStartDateTime ?start . }
    BIND (0 AS ?is_cancer_surgery) BIND (0 AS ?is_radiotherapy) BIND (1 AS ?is_billed_procedure)
  }
  BIND (YEAR(?start) AS ?year)
  FILTER (?year >= 2015 && ?year <= 2025)
}
GROUP BY ?year
ORDER BY ?year
